<?php
require (getenv('BL_WP_ROOT') ?: dirname(__DIR__, 2) . '/.test-wordpress') . '/wp-load.php';wp_set_current_user(1);
function verify($condition,$message){if(!$condition)throw new RuntimeException($message);echo 'PASS '.$message.PHP_EOL;}
$home=(int)get_option('page_on_front');$GLOBALS['wp_query']=new WP_Query(['page_id'=>$home]);$GLOBALS['post']=get_post($home);setup_postdata($GLOBALS['post']);
$slides=bl_field('hero_slides',$home);$new=array_reverse($slides);$third=$slides[0];$third['heading']='Third editable slide';$third['image']=bl_field('map_image','option');$new[]=$third;update_field('hero_slides',$new,$home);
ob_start();get_template_part('template-parts/hero');$html=ob_get_clean();verify(substr_count($html,'class="hero-slide"')===3,'adding hero slide changes slide count');verify(substr_count($html,'class="hero-dot"')===3,'slide controls follow repeater');verify(strpos($html,$new[0]['heading'])!==false || str_contains($html,'Fully IFRS-Aligned.'),'reordered hero content rendered');verify(str_contains($html,'Third editable slide'),'new slide PHP content rendered');update_field('hero_slides',$slides,$home);
foreach(['testimonials'=>'testimonials','branches'=>'branches-map','clients'=>'clients-summary'] as $field=>$part){$rows=bl_field($field,'option');update_field($field,[],'option');ob_start();get_template_part('template-parts/'.$part);$html=ob_get_clean();verify(trim($html)==='','empty '.$field.' section hidden');update_field($field,$rows,'option');}
$cta=bl_field('cta','option');$cleared=array_fill_keys(array_keys($cta),'');$cleared['icon']=$cta['icon'];update_field('cta',$cleared,'option');ob_start();get_template_part('template-parts/cta');$html=ob_get_clean();verify(trim($html)==='','empty CTA hidden despite decorative icon');update_field('cta',$cta,'option');
